// Parm(&Mode, &Id);

Event Start
&STSAuthorizationUserGUID.Visible = False &Online.Enabled = iif( &Mode = GAMAPiMode.Display, false, true) &MainMenu.AddItem(0,"GAM_none") BtnChangeClientSecret.Visible = False
If &Mode <> GAMAPiMode.Insert If &Mode = GAMAPiMode.Display OR &Mode = GAMAPiMode.Update BtnChangeClientSecret.Visible = True Endif &ClientSecret.Enabled = False &GAMApplication.Load(&Id) &Id = &GAMApplication.Id &GUID = &GAMApplication.GUID &Name = &GAMApplication.Name &Dsc = &GAMApplication.Description &Version = &GAMApplication.Version &Copyright = &GAMApplication.Copyright &Company = &GAMApplication.CompanyName &ReturnMenuOptionsWithoutPermission = &GAMApplication.ReturnMenuOptionsWithoutPermission &MainMenu = &GAMApplication.MainMenuId &UseAbsoluteUrlByEnvironment = &GAMApplication.UseAbsoluteUrlByEnvironment &HomeObject = &GAMApplication.HomeObject &AccountActivationObject = &GAMApplication.AccountActivationObject &LogoutObject = &GAMApplication.LogoutObject
//Authentication ////////// Tab Do 'ShowApplicationStatus' &ClientId = &GAMApplication.ClientId &ClientSecret = &GAMApplication.ClientSecret &ClientAuthRequestMustIncludeUserScopes = &GAMApplication.ClientAuthenticationRequestMustIncludeUserScopes &ClientDoNotShareUserIDs = &GAMApplication.ClientDoNotShareUserIDs //WEB Authentication &ClientAllowRemoteAuth = &GAMApplication.ClientAllowRemoteAuthentication &ClientAllowGetUserData = &GAMApplication.ClientAllowGetUserData &ClientAllowGetUserAddData = &GAMApplication.ClientAllowGetUserAdditionalData &ClientAllowGetUserRoles = &GAMApplication.ClientAllowGetUserRoles &ClientAllowGetSessionIniProp = &GAMApplication.ClientAllowGetSessionInitialProperties &ClientAllowGetSessionAppData = &GAMApplication.ClientAllowGetSessionApplicationData &ClientAllowAdditionalScope = &GAMApplication.ClientAllowAdditionalScope &ClientImageURL = &GAMApplication.ClientImageURL &ClientLocalLoginURL = &GAMApplication.ClientLocalLoginURL &ClientCallbackURL = &GAMApplication.ClientCallbackURL &ClientCallbackURLisCustom = &GAMApplication.ClientCallbackURLisCustom &ClientCallbackURLStateName = &GAMApplication.ClientCallbackURLStateName
//REST Authentication &ClientAllowRemoteRESTAuth = &GAMApplication.ClientAllowRemoteRESTAuthentication &ClientAllowGetUserDataREST = &GAMApplication.ClientAllowGetUserDataREST &ClientAllowGetUserAddDataREST = &GAMApplication.ClientAllowGetUserAdditionalDataREST &ClientAllowGetUserRolesREST = &GAMApplication.ClientAllowGetUserRolesREST &ClientAllowGetSessionIniPropREST = &GAMApplication.ClientAllowGetSessionInitialPropertiesREST &ClientAllowGetSessionAppDataREST = &GAMApplication.ClientAllowGetSessionApplicationDataREST &ClientAllowAdditionalScopeREST = &GAMApplication.ClientAllowAdditionalScopeREST
//Advanced OAuth Authentication &ClientAccessUniqueByUser = &GAMApplication.ClientAccessUniqueByUser &ClientEncryptionKey = &GAMApplication.ClientEncryptionKey &ClientRepositoryGUID = &GAMApplication.ClientRepositoryGUID
//Authorization ////////// Tab &AccessRequiresPermission = &GAMApplication.AccessRequiresPermission &IsAuthorizationDelegated = &GAMApplication.IsAuthorizationDelegated &DelegateAuthorizationVersion = &GAMApplication.DelegateAuthorization.Version &DelegateAuthorizationFileName = &GAMApplication.DelegateAuthorization.FileName &DelegateAuthorizationPackage = &GAMApplication.DelegateAuthorization.Package &DelegateAuthorizationClassName = &GAMApplication.DelegateAuthorization.ClassName &DelegateAuthorizationMethod = &GAMApplication.DelegateAuthorization.Method
//SSO REST ////////// Tab &SSORESTEnable = &GAMApplication.SSORESTEnable &SSORESTMode = &GAMApplication.SSORESTMode &SSORESTUserAuthTypeName = &GAMApplication.SSORESTUserAuthenticationTypeName &SSORESTServerURL = &GAMApplication.SSORESTServerURL &SSORESTServerURL_isCustom = &GAMApplication.SSORESTServerURL_isCustom &SSORESTServerURL_SLO = &GAMApplication.SSORESTServerURL_SLO &SSORESTServerRepositoryGUID = &GAMApplication.SSORESTServerRepositoryGUID &SSORESTServerKey = &GAMApplication.SSORESTServerKey
//STS Protocol ////////// Tab &STSProtocolEnable = &GAMApplication.STSProtocolEnable If not &GAMApplication.STSAuthorizationUserGUID.IsEmpty() &GAMUser.Load(&GAMApplication.STSAuthorizationUserGUID) &STSAuthorizationUserName = &GAMUser.Name Endif &STSMode = &GAMApplication.STSMode &STSServerURL = &GAMApplication.STSServerURL &STSServerClientPassword = &GAMApplication.STSServerClientPassword &STSServerRepositoryGUID = &GAMApplication.STSServerRepositoryGUID
//Mini App ////////// Tab &MiniAppEnable = &GAMApplication.MiniAppEnable &MiniAppMode = &GAMApplication.MiniAppMode &MiniAppClientURL = &GAMApplication.MiniAppClientURL &MiniAppClientURL_isCustom = &GAMApplication.MiniAppClientURL_isCustom &MiniAppClientRepositoryGUID = &GAMApplication.MiniAppClientRepositoryGUID &MiniAppUserAuthenticationTypeName = &GAMApplication.MiniAppUserAuthenticationTypeName &MiniAppServerURL = &GAMApplication.MiniAppServerURL &MiniAppServerURL_isCustom = &GAMApplication.MiniAppServerURL_isCustom &MiniAppServerRepositoryGUID = &GAMApplication.MiniAppServerRepositoryGUID
//API key ////////// Tab &APIKeyEnable = &GAMApplication.APIKeyEnable &APIKeyTimeout = &GAMApplication.APIKeyTimeout &APIKeyAllowOnlyAuthenticationTypeName = &GAMApplication.APIKeyAllowOnlyAuthenticationTypeName &APIKeyAllowScopeCustomization = &GAMApplication.APIKeyAllowScopeCustomization
//Environment ////////// Tab &EnvironmentName = &GAMApplication.Environment.Name &EnvironmentSecureProtocol = &GAMApplication.Environment.SecureProtocol &EnvironmentHost = &GAMApplication.Environment.Host &EnvironmentPort = &GAMApplication.Environment.Port &EnvironmentVirtualDirectory= &GAMApplication.Environment.VirtualDirectory &EnvironmentProgramPackage = &GAMApplication.Environment.ProgramPackage &EnvironmentProgramExtension= &GAMApplication.Environment.ProgramExtension
//Main Menu ///// Combo For &Menu in &GAMApplication.GetMenus(&MenuFilter, &GAMErrorCollection) &MainMenu.AddItem(&Menu.Id, &Menu.Name) Endfor Else &ClientSecret.Enabled = True &ClientAuthRequestMustIncludeUserScopes = True Endif If &Mode = GAMAPiMode.Display or &Mode = GAMAPiMode.Delete &GUID.Enabled = False &Name.Enabled = False &Dsc.Enabled = False &Version.Enabled = False &Copyright.Enabled = False &Company.Enabled = False &ReturnMenuOptionsWithoutPermission.Enabled = False &MainMenu.Enabled = False &UseAbsoluteUrlByEnvironment.Enabled = False &HomeObject.Enabled = False &AccountActivationObject.Enabled = False &LogoutObject.Enabled = False
//Authentication ////////// Tab &ClientId.Enabled = False &ClientSecret.Enabled = False &ClientAuthRequestMustIncludeUserScopes.Enabled = False &ClientDoNotShareUserIDs.Enabled = False
&ClientAllowRemoteAuth.Enabled = False &ClientAllowGetUserData.Enabled = False &ClientAllowGetUserAddData.Enabled = False &ClientAllowGetUserRoles.Enabled = False &ClientAllowGetSessionIniProp.Enabled = False &ClientAllowGetSessionAppData.Enabled = False &ClientAllowAdditionalScope.Enabled = False &ClientImageURL.Enabled = False &ClientLocalLoginURL.Enabled = False &ClientCallbackURL.Enabled = False &ClientCallbackURLisCustom.Enabled = False &ClientCallbackURLStateName.Enabled = False
&ClientAllowRemoteRESTAuth.Enabled = False &ClientAllowGetUserDataREST.Enabled = False &ClientAllowGetUserAddDataREST.Enabled = False &ClientAllowGetUserRolesREST.Enabled = False &ClientAllowGetSessionIniPropREST.Enabled = False &ClientAllowGetSessionAppDataREST.Enabled = False &ClientAllowAdditionalScopeREST.Enabled = False
&ClientAccessUniqueByUser.Enabled = False &ClientEncryptionKey.Enabled = False &ClientRepositoryGUID.Enabled = False
//Authorization ////////// Tab &AccessRequiresPermission.Enabled = False &IsAuthorizationDelegated.Enabled = False &DelegateAuthorizationVersion.Enabled = False &DelegateAuthorizationFileName.Enabled = False &DelegateAuthorizationPackage.Enabled = False &DelegateAuthorizationClassName.Enabled = False &DelegateAuthorizationMethod.Enabled = False //SSO REST ////////// Tab &SSORESTEnable.Enabled = False &SSORESTMode.Enabled = False &SSORESTUserAuthTypeName.Enabled = False &SSORESTServerURL.Enabled = False &SSORESTServerURL_isCustom.Enabled = False &SSORESTServerURL_SLO.Enabled = False &SSORESTServerRepositoryGUID.Enabled = False &SSORESTServerKey.Enabled = False //STS ////////// Tab &STSProtocolEnable.Enabled = False &STSAuthorizationUserName.Enabled = False &STSMode.Enabled = False &STSServerURL.Enabled = False &STSServerClientPassword.Enabled = False &STSServerRepositoryGUID.Enabled = False //MiniApp ////////// Tab &MiniAppEnable.Enabled = False &MiniAppMode.Enabled = False &MiniAppClientURL.Enabled = False &MiniAppClientURL_isCustom.Enabled = False &MiniAppClientRepositoryGUID.Enabled = False &MiniAppUserAuthenticationTypeName.Enabled = False &MiniAppServerURL.Enabled = False &MiniAppServerURL_isCustom.Enabled = False &MiniAppServerRepositoryGUID.Enabled = False //API key ////////// Tab &APIKeyEnable.Enabled = False &APIKeyTimeout.Enabled = False &APIKeyAllowOnlyAuthenticationTypeName.Enabled = False &APIKeyAllowScopeCustomization.Enabled = False
&EnvironmentName.Enabled = False &EnvironmentSecureProtocol.Enabled = False &EnvironmentHost.Enabled = False &EnvironmentPort.Enabled = False &EnvironmentVirtualDirectory.Enabled = False &EnvironmentProgramPackage.Enabled = False &EnvironmentProgramExtension.Enabled = False BtnGenerateKeyGAMRemote.Visible = False If &GAMApplication.ClientRevoked.IsEmpty() BtnRevokeAllow.Caption = "WWP_GAM_Revoke" Else BtnRevokeAllow.Caption = "WWP_GAM_Authorize" Endif If &Mode = GAMAPiMode.Delete BtnEnter.Caption = "GAM_Delete" Endif Endif Do "UI_RemoteAuthenticationWeb" Do "UI_RemoteAuthenticationREST" Do "UI_DelegateAuthorization" Do "UI_SSOREST" Do "UI_STSProtocol" Do "UI_MiniApp" Do "UI_APIKey" If &Mode = GAMAPiMode.Display BtnEnter.Visible = False Endif
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
//Code block: EditFormClass LayoutMainTable.Class = LayoutMainTable.Class + " " + ThemeClass:EditForm
Do 'AttributesSecurityCode' &AutoRegisterAnomymousUser.Visible = False &STSAuthorizationUserGUID.Visible = False GridLanguages_Empowerer.GridInternalName = GridLanguages.InternalName GridLanguages.Rows = Page.Rows &GridLanguagesCurrentPage = 1 &GridLanguagesCurrentPage.Visible = False &GridLanguagesPageCount = -1 GridLanguagesPaginationBar.RowsPerPageSelectedValue = GridLanguages.Rows
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event Refresh
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
//The variable '&GridLanguagesPageCount' must be assigned manually in order to get a correct behaviour of the Pagination Bar.
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event GridLanguages.Load
Do "LoadLanguages"
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
//this code should be inside the For Each used to load the grid
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event GridLanguagesPaginationBar.ChangePage
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
Do Case Case GridLanguagesPaginationBar.SelectedPage = !'Previous' &GridLanguagesCurrentPage -= 1 GridLanguages.PreviousPage() Case GridLanguagesPaginationBar.SelectedPage = !'Next' &GridLanguagesCurrentPage += 1 GridLanguages.NextPage() Otherwise &PageToGo.FromString(GridLanguagesPaginationBar.SelectedPage) &GridLanguagesCurrentPage = &PageToGo GridLanguages.GotoPage(&PageToGo) EndCase Refresh
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event GridLanguagesPaginationBar.ChangeRowsPerPage
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
GridLanguages.Rows = GridLanguagesPaginationBar.RowsPerPageSelectedValue &GridLanguagesCurrentPage = 1 GridLanguages.FirstPage()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event 'DoChangeClientSecret'
&Window.Object = Create(GAMApplicationClientSecret, &ClientId) &Window.Open() GAMApplicationEntry(GAMAPIMode.Display, &Id)
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event 'DoGenerateKeyGAMRemote'
&ClientEncryptionKey = GetEncryptionKey()
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Event 'DoRevokeAllow'
&GAMApplication.Load(&Id) If &GAMApplication.ClientRevoked.IsEmpty() &isOk = &GAMApplication.RevokeClient(&Errors) Else &isOk = &GAMApplication.AuthorizeClient(&Errors) Endif If &isOk If &GAMApplication.ClientRevoked.IsEmpty() BtnRevokeAllow.Caption = "WWP_GAM_Revoke" Else BtnRevokeAllow.Caption = "WWP_GAM_Authorize" Endif Commit Refresh Else Do 'Errors' EndIf
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndEvent
Sub 'AttributesSecurityCode'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If Not (&STSMode = GAMSTSModes.ClientFull Or &STSMode = GAMSTSModes.ClientGetToken) &STSServerClientPassword.Visible = False STSServerClientPassword_Cell.Class = !'Invisible' Else &STSServerClientPassword.Visible = True STSServerClientPassword_Cell.Class = !'col-xs-12 DataContentCell' EndIf If &STSServerClientPassword.Visible = False TableSTSClientGetToken.Visible = False EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Event Enter
If &Mode <> TrnMode.Insert &GAMApplication.Load(&Id) Endif Do Case Case &Mode = GAMAPiMode.Insert or &Mode = GAMAPiMode.Update &GAMApplication.Name = &Name &GAMApplication.Description = &Dsc &GAMApplication.Version = &Version &GAMApplication.Copyright = &Copyright &GAMApplication.CompanyName = &Company &GAMApplication.ReturnMenuOptionsWithoutPermission = &ReturnMenuOptionsWithoutPermission &GAMApplication.MainMenuId = &MainMenu &GAMApplication.UseAbsoluteUrlByEnvironment = &UseAbsoluteUrlByEnvironment &GAMApplication.HomeObject = &HomeObject &GAMApplication.AccountActivationObject = &AccountActivationObject &GAMApplication.LogoutObject = &LogoutObject
//Authentication ////////// Tab &GAMApplication.ClientId = &ClientId &GAMApplication.ClientSecret = &ClientSecret &GAMApplication.ClientAuthenticationRequestMustIncludeUserScopes= &ClientAuthRequestMustIncludeUserScopes &GAMApplication.ClientDoNotShareUserIDs = &ClientDoNotShareUserIDs
&GAMApplication.ClientAccessUniqueByUser = &ClientAccessUniqueByUser &GAMApplication.ClientAllowRemoteAuthentication = &ClientAllowRemoteAuth &GAMApplication.ClientAllowGetUserData = &ClientAllowGetUserData &GAMApplication.ClientAllowGetUserAdditionalData = &ClientAllowGetUserAddData &GAMApplication.ClientAllowGetUserRoles = &ClientAllowGetUserRoles &GAMApplication.ClientAllowGetSessionInitialProperties = &ClientAllowGetSessionIniProp &GAMApplication.ClientAllowGetSessionApplicationData = &ClientAllowGetSessionAppData &GAMApplication.ClientAllowAdditionalScope = &ClientAllowAdditionalScope &GAMApplication.ClientLocalLoginURL = &ClientLocalLoginURL &GAMApplication.ClientCallbackURL = &ClientCallbackURL &GAMApplication.ClientCallbackURLisCustom = &ClientCallbackURLisCustom &GAMApplication.ClientCallbackURLStateName = &ClientCallbackURLStateName &GAMApplication.ClientImageURL = &ClientImageURL &GAMApplication.ClientAllowRemoteRESTAuthentication = &ClientAllowRemoteRESTAuth &GAMApplication.ClientAllowGetUserDataREST = &ClientAllowGetUserDataREST &GAMApplication.ClientAllowGetUserAdditionalDataREST = &ClientAllowGetUserAddDataREST &GAMApplication.ClientAllowGetUserRolesREST = &ClientAllowGetUserRolesREST &GAMApplication.ClientAllowGetSessionInitialPropertiesREST = &ClientAllowGetSessionIniPropREST &GAMApplication.ClientAllowGetSessionApplicationDataREST = &ClientAllowGetSessionAppDataREST &GAMApplication.ClientAllowAdditionalScopeREST = &ClientAllowAdditionalScopeREST &GAMApplication.ClientEncryptionKey = &ClientEncryptionKey &GAMApplication.ClientRepositoryGUID = &ClientRepositoryGUID //Authorization ////////// Tab &GAMApplication.AccessRequiresPermission = &AccessRequiresPermission &GAMApplication.IsAuthorizationDelegated = &IsAuthorizationDelegated &GAMApplication.DelegateAuthorization.Version = &DelegateAuthorizationVersion &GAMApplication.DelegateAuthorization.FileName = &DelegateAuthorizationFileName &GAMApplication.DelegateAuthorization.Package = &DelegateAuthorizationPackage &GAMApplication.DelegateAuthorization.ClassName = &DelegateAuthorizationClassName &GAMApplication.DelegateAuthorization.Method = &DelegateAuthorizationMethod //SSO REST ////////// Tab &GAMApplication.SSORESTEnable = &SSORESTEnable &GAMApplication.SSORESTMode = &SSORESTMode &GAMApplication.SSORESTUserAuthenticationTypeName = &SSORESTUserAuthTypeName &GAMApplication.SSORESTServerURL = &SSORESTServerURL &GAMApplication.SSORESTServerURL_isCustom = &SSORESTServerURL_isCustom &GAMApplication.SSORESTServerURL_SLO = &SSORESTServerURL_SLO &GAMApplication.SSORESTServerRepositoryGUID = &SSORESTServerRepositoryGUID &GAMApplication.SSORESTServerKey = &SSORESTServerKey //STS ////////// Tab &GAMApplication.STSProtocolEnable = &STSProtocolEnable If not &STSAuthorizationUserName.IsEmpty() &GAMUser = &GAMUser.GetByLogin(!"local", &STSAuthorizationUserName,&UserErrors) &STSAuthorizationUserGUID = &GAMUser.GUID Endif &GAMApplication.STSAuthorizationUserGUID = &STSAuthorizationUserGUID &GAMApplication.STSMode = &STSMode &GAMApplication.STSServerURL = &STSServerURL &GAMApplication.STSServerClientPassword = &STSServerClientPassword &GAMApplication.STSServerRepositoryGUID = &STSServerRepositoryGUID //MiniApp ////////// Tab &GAMApplication.MiniAppEnable = &MiniAppEnable &GAMApplication.MiniAppMode = &MiniAppMode &GAMApplication.MiniAppClientURL = &MiniAppClientURL &GAMApplication.MiniAppClientURL_isCustom = &MiniAppClientURL_isCustom &GAMApplication.MiniAppClientRepositoryGUID = &MiniAppClientRepositoryGUID &GAMApplication.MiniAppUserAuthenticationTypeName = &MiniAppUserAuthenticationTypeName &GAMApplication.MiniAppServerURL = &MiniAppServerURL &GAMApplication.MiniAppServerURL_isCustom = &MiniAppServerURL_isCustom &GAMApplication.MiniAppServerRepositoryGUID = &MiniAppServerRepositoryGUID //API key ////////// Tab &GAMApplication.APIKeyEnable = &APIKeyEnable &GAMApplication.APIKeyTimeout = &APIKeyTimeout &GAMApplication.APIKeyAllowOnlyAuthenticationTypeName = &APIKeyAllowOnlyAuthenticationTypeName &GAMApplication.APIKeyAllowScopeCustomization = &APIKeyAllowScopeCustomization //Environment ////////// Tab &GAMApplication.Environment.Name = &EnvironmentName &GAMApplication.Environment.SecureProtocol = &EnvironmentSecureProtocol &GAMApplication.Environment.Host = &EnvironmentHost &GAMApplication.Environment.Port = &EnvironmentPort &GAMApplication.Environment.VirtualDirectory = &EnvironmentVirtualDirectory &GAMApplication.Environment.ProgramPackage = &EnvironmentProgramPackage &GAMApplication.Environment.ProgramExtension = &EnvironmentProgramExtension //Languages ////////// Tab Do 'SaveLanguages' &GAMApplication.Save() Case &Mode = GAMAPiMode.Delete &GAMApplication.Delete() EndCase If &GAMApplication.Success() and &UserErrors.Count = 0 Commit GAMWWApplications.Link() Else &Errors = &GAMApplication.GetErrors() Do 'Errors' EndIf
EndEvent
Event &ClientAllowRemoteAuth.ControlValueChanged
Do "UI_RemoteAuthenticationWeb" If &Mode = GAMAPiMode.Insert AND &ClientAllowRemoteAuth = True &ClientAllowGetUserData = True Endif
EndEvent
Event &ClientAllowRemoteRESTAuth.ControlValueChanged
Do "UI_RemoteAuthenticationREST" If &Mode = GAMAPiMode.Insert AND &ClientAllowRemoteRESTAuth = True &ClientAllowGetUserDataREST = True Endif
EndEvent
Event &AccessRequiresPermission.IsValid
Do "UI_DelegateAuthorization"
EndEvent
Event &IsAuthorizationDelegated.IsValid
Do "UI_DelegateAuthorization"
EndEvent
Event 'GenerateKeyGAMRemote'
&ClientEncryptionKey = GetEncryptionKey()
EndEvent
Event 'Revoke-Authorize'
&GAMApplication.Load(&Id) If not &GAMApplication.ClientRevoked.IsEmpty() &isOk = &GAMApplication.RevokeClient(&GAMErrorCollection) Msg(Format("WWP_GAM_Theapplication1wasrevoked", &GAMApplication.Name)) Else &isOk = &GAMApplication.AuthorizeClient(&GAMErrorCollection) Msg(Format("WWP_GAM_Theapplication1wasactivated", &GAMApplication.Name)) Endif If &isOk Commit Do 'ShowApplicationStatus' Endif &Errors = &GAMErrorCollection Do 'Errors'
EndEvent
Event 'Translations'
&Window.Object = Create(GAMTranslations, &Mode, !"Application", &Name, &Id, 0, 0) &Window.Open() Refresh
EndEvent
Event &SSORESTEnable.ControlValueChanged
Do "UI_SSOREST"
EndEvent
Event &SSORESTMode.ControlValueChanged
Do "UI_SSOREST"
EndEvent
Event &STSMode.ControlValueChanged
Do "UI_STSProtocol"
EndEvent
Event &STSProtocolEnable.ControlValueChanged
Do "UI_STSProtocol"
EndEvent
Event &MiniAppEnable.ControlValueChanged
Do "UI_MiniApp"
EndEvent
Event &MiniAppMode.ControlValueChanged
Do "UI_MiniApp"
EndEvent
Event &APIKeyEnable.ControlValueChanged
Do "UI_APIKey"
EndEvent
Event &ClientAllowRemoteAuth.Click
Do "UI_RemoteAuthenticationWeb"
EndEvent
Event &ClientAllowRemoteRestAuth.Click
Do "UI_RemoteAuthenticationRest"
EndEvent
Event &SSORestMode.Click
Do "UI_SSORest"
EndEvent
Event &STSProtocolEnable.Click
Do "UI_STSProtocol"
EndEvent
Event &STSMode.Click
Do Case Case &STSMode = GAMSTSModes.Server TableSTSServerCheckToken.Visible = True TableSTSClient.Visible = False Case &STSMode = GAMSTSModes.ClientGetToken TableSTSServerCheckToken.Visible = False TableSTSClient.Visible = True Case &STSMode = GAMSTSModes.ClientCheckToken TableSTSServerCheckToken.Visible = True TableSTSClient.Visible = True Case &STSMode = GAMSTSModes.ClientFull TableSTSServerCheckToken.Visible = True TableSTSClient.Visible = True EndCase Do 'AttributesSecurityCode'
EndEvent
Event &SSORestEnable.Click
Do "UI_SSORest"
EndEvent
Sub 'Errors'
If &Errors.Count > 0 For &Error in &Errors Msg(Format(!"%1 (GAM%2)", &Error.Message, &Error.Code)) EndFor EndIf If &UserErrors.Count > 0 For &Error in &UserErrors Msg(Format(!"%1 (GAM%2)", &Error.Message, &Error.Code)) EndFor EndIf
EndSub
Sub 'ShowApplicationStatus'
If &GAMApplication.ClientRevoked.IsEmpty() BtnRevokeAllow.Caption = "GAM_Revoke" &ClientAccessStatus = GAMGeneralStatus.On &ClientRevoked.Visible = False Else BtnRevokeAllow.Caption = "GAM_Activate" &ClientAccessStatus = GAMGeneralStatus.Off &ClientRevoked.Visible = True &ClientRevoked = &GAMApplication.ClientRevoked Endif
EndSub
Sub "UI_RemoteAuthenticationWeb"
If &ClientAllowRemoteAuth TblWebAuth.Visible = True TblGeneralAuth.Visible = True Else TblWebAuth.Visible = False If not &ClientAllowRemoteRESTAuth TblGeneralAuth.Visible = False Endif Endif
EndSub
Sub "UI_RemoteAuthenticationREST"
If &ClientAllowRemoteRESTAuth TblRESTAuth.Visible = True TblGeneralAuth.Visible = True Else TblRESTAuth.Visible = False If not &ClientAllowRemoteAuth TblGeneralAuth.Visible = False Endif Endif
EndSub
Sub "UI_DelegateAuthorization"
If &AccessRequiresPermission TblDelegateAuthorization.Visible = True If &IsAuthorizationDelegated TblDelegateAuthorizationProp.Visible = True Else TblDelegateAuthorizationProp.Visible = False Endif Else TblDelegateAuthorization.Visible = False Endif
EndSub
Sub "UI_SSOREST"
If &SSORESTEnable Do "GetListAuthenticationTypeSSOREST" TableSSOREST.Visible = True TblSSORESTModeClient.Visible = False Do Case Case &SSORESTMode = GAMAppConnectionModes.Server TblSSORESTModeClient.Visible = False Case &SSORESTMode = GAMAppConnectionModes.Client TblSSORESTModeClient.Visible = True EndCase Else TableSSOREST.Visible = False Endif
EndSub
Sub "UI_STSProtocol"
If &STSProtocolEnable TableSTS.Visible = True Do Case Case &STSMode = GAMSTSModes.Server TableSTSServerCheckToken.Visible = True TableSTSClientGetToken.Visible = False TableSTSClient.Visible = False Case &STSMode = GAMSTSModes.ClientGetToken TableSTSServerCheckToken.Visible = False TableSTSClientGetToken.Visible = True TableSTSClient.Visible = True Case &STSMode = GAMSTSModes.ClientCheckToken TableSTSServerCheckToken.Visible = True TableSTSClientGetToken.Visible = False TableSTSClient.Visible = True Case &STSMode = GAMSTSModes.ClientFull TableSTSServerCheckToken.Visible = True TableSTSClientGetToken.Visible = True TableSTSClient.Visible = True EndCase Else TableSTS.Visible = False Endif
EndSub
Sub "UI_MiniApp"
If &MiniAppEnable TblMiniApp.Visible = True Do "GetListAuthenticationTypeMiniApp" TblMiniAppServer.Visible = False TblMiniAppClient.Visible = False Do Case Case &MiniAppMode = GAMAppConnectionModes.Server TblMiniAppServer.Visible = True Case &MiniAppMode = GAMAppConnectionModes.Client TblMiniAppClient.Visible = True EndCase Else TblMiniApp.Visible = False Endif
EndSub
Sub "UI_APIKey"
If &APIKeyEnable TblAPIKey.Visible = True Do "GetListAuthenticationTypeAPIKey" Else TblAPIKey.Visible = False Endif
EndSub
Sub "GetListAuthenticationTypeSSOREST"
&GAMAuthenticationTypeFilter = new() &GAMAuthenticationTypeFilter.CanUsersBeDefined = GAMBooleanFilter.True For &AuthenticationType in GAMRepository.GetAuthenticationTypes(&GAMAuthenticationTypeFilter, &GAMErrorCollection) // &SSORESTUserAuthTypeName.AddItem(&AuthenticationType.Name, &AuthenticationType.Name) Endfor
EndSub
Sub "GetListAuthenticationTypeMiniApp"
&GAMAuthenticationTypeFilter = new() &GAMAuthenticationTypeFilter.CanUsersBeDefined = GAMBooleanFilter.True For &AuthenticationType in GAMRepository.GetAuthenticationTypes(&GAMAuthenticationTypeFilter, &GAMErrorCollection) &MiniAppUserAuthenticationTypeName.AddItem(&AuthenticationType.Name, &AuthenticationType.Name) Endfor
EndSub
Sub "GetListAuthenticationTypeAPIKey"
&GAMAuthenticationTypeFilter = new() &GAMAuthenticationTypeFilter.Type = GAMAuthenticationTypes.APIkey For &AuthenticationType in GAMRepository.GetAuthenticationTypes(&GAMAuthenticationTypeFilter, &GAMErrorCollection) &APIKeyAllowOnlyAuthenticationTypeName.AddItem(&AuthenticationType.Name, &AuthenticationType.Name) Endfor
EndSub
Sub 'LoadLanguages'
&GAMLanguages = GeneXusSecurity.GAM.GetLanguages(&GAMApplication.Languages) For &GAMLanguage in &GAMLanguages &Online = &GAMLanguage.Online &Language = &GAMLanguage.Name If &Mode = TrnMode.Insert OR &Mode = TrnMode.Update GridLanguages.Load() Else If &Online GridLanguages.Load() Endif Endif EndFor
EndSub
Sub 'SaveLanguages'
&GAMLanguages = GeneXusSecurity.GAM.GetLanguages(&GAMApplication.Languages) For each line For &GAMLanguage in &GAMLanguages If &GAMLanguage.Name = &Language &GAMLanguage.Online = &Online Endif EndFor Endfor &GAMApplication.Languages = &GAMLanguages
EndSub
